unsigned flac_process_audio_loop(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_read = 0;
    unsigned remaining = len;
    FLAC__byte *buffer = psf->buffer;

    if (!psf || !buffer) {
        psf_log(psf, "Invalid private state or buffer");
        return 0;
    }

    if (psf->flac_decoder.state != FLAC__DECODER_STATE_DECODING) {
        psf_log(psf, "Decoder is not in decoding state");
        return 0;
    }

    while (remaining > 0 && psf->flac_decoder.state != FLAC__DECODER_STATE_END_OF_STREAM) {
        unsigned frame_bytes = 0;

        if (psf->flac_decoder.current_frame) {
            frame_bytes = psf->flac_decoder.frame_remaining;
            if (frame_bytes > remaining)
                frame_bytes = remaining;

            memcpy(buffer + bytes_read, psf->flac_decoder.frame_buffer + psf->flac_decoder.frame_pos, frame_bytes);
            psf->flac_decoder.frame_pos += frame_bytes;
            psf->flac_decoder.frame_remaining -= frame_bytes;
            bytes_read += frame_bytes;
            remaining -= frame_bytes;
        }

        if (psf->flac_decoder.frame_remaining == 0) {
            if (flac_decode_next_frame(psf) != 0) {
                psf_log(psf, "Failed to decode next frame");
                psf->flac_decoder.frame = NULL;
            }
        }
    }

    return bytes_read;
}

unsigned flac_process_audio_loop(SF_PRIVATE *psf, unsigned len) {
    unsigned total_read = 0;
    unsigned bytes_read;
    unsigned short frame_remaining;
    const char *frame_data = NULL;

    if (!psf || len == 0)
        return 0;

    if (psf->flac.frame_remaining == 0 && psf->flac.decoder_state != SF_DECODER_EOS) {
        if (psf->flac.decoder_state != SF_DECODER_OK) {
            SF_LOG(psf, SF_LOG_WARNING, "FLAC decoder in invalid state.");
            psf->flac.frame_ptr = NULL;
            return 0;
        }

        if (psf->flac.frame_ptr != NULL) {
            frame_data = psf->flac.frame_ptr + psf->flac.frame_pos;
            frame_remaining = psf->flac.frame_remaining;
        }
    }

    while (total_read < len && psf->flac.decoder_state != SF_DECODER_EOS) {
        if (frame_data && frame_remaining > 0) {
            bytes_read = (unsigned) SF_MIN(frame_remaining, len - total_read);
            memcpy(psf->current_buffer + total_read, frame_data, bytes_read);
            total_read += bytes_read;
            frame_remaining -= bytes_read;
            frame_data += bytes_read;
            psf->flac.frame_remaining = frame_remaining;
            psf->flac.frame_pos += bytes_read;

            if (frame_remaining == 0) {
                psf->flac.frame_ptr = NULL;
            }

            continue;
        }

        // Simulate decoding one frame (this would be replaced with actual FLAC decoding logic)
        bytes_read = decode_flac_frame(psf, psf->current_buffer + total_read, len - total_read);
        if (bytes_read == 0) {
            if (psf->flac.decoder_state != SF_DECODER_EOS) {
                SF_LOG(psf, SF_LOG_ERROR, "FLAC decoding failed.");
                psf->flac.frame_ptr = NULL;
                break;
            }
        }

        total_read += bytes_read;
    }

    return total_read;
}

unsigned flac_decoder_audio_read_loop(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_read = 0;
    unsigned pos = 0;
    unsigned remaining = len;

    if (psf == NULL) {
        return 0;
    }

    if (psf->frame && psf->frame_remaining > 0) {
        unsigned copy_len = SF_MIN(psf->frame_remaining, remaining);
        memcpy(psf->output_buffer + pos, psf->frame_buffer, copy_len);
        pos += copy_len;
        bytes_read += copy_len;
        remaining -= copy_len;
        psf->frame_buffer += copy_len;
        psf->frame_remaining -= copy_len;
    }

    while (remaining > 0) {
        if (psf->decoder_state != SF_CODEC_OK) {
            psf_log_printf(psf, "FLAC decoder error: %s\n", sf_error_str(psf));
            psf->frame = NULL;
            break;
        }

        if (psf->frame == NULL || psf->frame_remaining == 0) {
            if (!flac_decoder_read_frame(psf)) {
                break;
            }
        }

        unsigned copy_len = SF_MIN(psf->frame_remaining, remaining);
        memcpy(psf->output_buffer + pos, psf->frame_buffer, copy_len);
        pos += copy_len;
        bytes_read += copy_len;
        remaining -= copy_len;
        psf->frame_buffer += copy_len;
        psf->frame_remaining -= copy_len;
    }

    return bytes_read;
}

unsigned flac_process_audio_data(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_read = 0;
    unsigned remaining = len;
    unsigned char *ptr = psf->data;
    unsigned frame_size = 0;

    if (psf->flac_frame == NULL) {
        psf_log_printf(psf, "FLAC frame is not initialized.\n");
        return 0;
    }

    while (remaining > 0 && psf->flac_decoder_state != FLAC__STREAM_DECODER_END_OF_STREAM) {
        if (psf->flac_decoder_state != FLAC__STREAM_DECODER_READ_FRAME) {
            psf_log_printf(psf, "Unexpected FLAC decoder state: %d.\n", psf->flac_decoder_state);
            break;
        }

        frame_size = flac_frame_get_blocksize(psf->flac_frame);

        if (frame_size == 0) {
            psf_log_printf(psf, "FLAC frame size is zero.\n");
            break;
        }

        if (remaining >= frame_size) {
            memcpy(ptr, psf->flac_buffer, frame_size);
            ptr += frame_size;
            psf->flac_buffer += frame_size;
            bytes_read += frame_size;
            remaining -= frame_size;
        } else {
            memcpy(ptr, psf->flac_buffer, remaining);
            ptr += remaining;
            psf->flac_buffer += remaining;
            bytes_read += remaining;
            remaining = 0;
        }
    }

    if (psf->flac_decoder_state == FLAC__STREAM_DECODER_ERROR) {
        psf_log_printf(psf, "FLAC decoder error occurred.\n");
        psf->flac_frame = NULL;
    }

    return bytes_read;
}

unsigned process_flac_audio_data(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_read = 0;
    unsigned remaining = len;
    unsigned char *buffer = psf->buffer;

    if (psf->flac.frame == NULL) {
        return 0;
    }

    while (remaining > 0) {
        if (psf->flac.decoder_state == SF_DECODER_ERROR) {
            sf_log(psf, SF_LOG_ERROR, "FLAC decoder in error state");
            psf->flac.frame = NULL;
            break;
        }

        if (psf->flac.decoder_state == SF_DECODER_EOS) {
            break;
        }

        if (psf->flac.buffered_samples > 0) {
            unsigned to_copy = (remaining < psf->flac.buffered_samples) ?
                               remaining : psf->flac.buffered_samples;
            memcpy(buffer, psf->flac.buffer, to_copy);
            buffer += to_copy;
            psf->flac.buffer += to_copy;
            psf->flac.buffered_samples -= to_copy;
            bytes_read += to_copy;
            remaining -= to_copy;
            continue;
        }

        if (!flac_decode_audio(psf)) {
            sf_log(psf, SF_LOG_ERROR, "Failed to decode audio frame");
            psf->flac.frame = NULL;
            break;
        }
    }

    return bytes_read;
}
